// orchestrator.rs — Phase 1: Approval

let requirement = tool
  .exec_approval_requirement(req)
  .unwrap_or_else(|| {
    default_exec_approval_requirement(
      AskForApproval::OnFailure,        // 策略
      &FileSystemSandboxKind::Restricted, // 沙箱类型
    )
  });

// OnFailure + Restricted → Skip
// → match requirement {
//     ExecApprovalRequirement::Skip { .. } =>
//       otel.tool_decision(otel_tn, otel_ci,
//         &ReviewDecision::Approved,
//         ToolDecisionSource::Config),
//   }
// already_approved = false（Config 决定，非用户）

// orchestrator.rs — Phase 2: First Attempt

let initial_sandbox = self.sandbox.select_initial(
  &turn_ctx.file_system_sandbox_policy,
  turn_ctx.network_sandbox_policy,
  tool.sandbox_preference(),  // Auto
  turn_ctx.windows_sandbox_level,
  managed_network_active,     // false
);
// → SandboxType::LinuxSeccomp

let initial_attempt = SandboxAttempt {
  sandbox: SandboxType::LinuxSeccomp,
  policy: &turn_ctx.sandbox_policy,
  ..
};

Self::run_attempt(tool, req, tool_ctx,
  &initial_attempt, managed_network_active).await
// → (Ok(ExecToolCallOutput { exit_code: 0 }), None)

// orchestrator.rs — Phase 1: Approval

// exec_policy.rs: check_command(["rm","-rf","/tmp/build-cache"])
// → command_might_be_dangerous() → true (rm -rf)
// → Decision::Prompt
//
// default_exec_approval_requirement(
//   AskForApproval::UnlessTrusted,
//   FileSystemSandboxKind::Restricted,
// ) → ExecApprovalRequirement::NeedsApproval {
//     reason: Some("rm -rf 需要批准"),
//     proposed_execpolicy_amendment: None,
//   }

let decision = tool.start_approval_async(
  req,
  ApprovalCtx {
    retry_reason: Some("rm -rf 需要批准"),
    ..
  }
).await;
// → 等待 TUI 用户响应

// TUI 显示审批界面:
// ┌─────────────────────────────────────┐
// │ 工具调用需要批准                     │
// │ 命令: rm -rf /tmp/build-cache       │
// │ 原因: rm -rf 需要批准               │
// │                                     │
// │ [批准] [批准(本次session)] [拒绝]   │
// └─────────────────────────────────────┘

// 用户选择: ReviewDecision::ApprovedForSession
// → match decision {
//     ReviewDecision::ApprovedForSession => {}
//     // 继续执行，already_approved = true
//   }
// otel.tool_decision(..., ToolDecisionSource::User)

// Phase 2 结果: SandboxErr::Denied
// → is_likely_sandbox_denied() 检测到 /tmp 路径
//   超出 WorkspaceWrite.writable_roots

// orchestrator.rs 匹配:
// Err(ToolError::Codex(CodexErr::Sandbox(
//   SandboxErr::Denied { output, .. }
// )))

// escalate_on_failure() → true
// wants_no_sandbox_approval(UnlessTrusted) → true

// build_denial_reason_from_output():
// → "command failed; retry without sandbox?"

// bypass_retry_approval = false (已批准但需再次确认升级)
// 再次调用 start_approval_async() 询问用户

// Phase 3: Escalation retry
// 用户再次批准后:

let escalated_attempt = SandboxAttempt {
  sandbox: SandboxType::None, // 移除沙箱限制
  policy: &turn_ctx.sandbox_policy,
  ..
};

Self::run_attempt(tool, req, tool_ctx,
  &escalated_attempt,
  managed_network_active
).await
// → (Ok(ExecToolCallOutput { exit_code: 0 }), None)

